import{_ as o,o as t,c as r,a2 as a}from"./chunks/framework.BOeh4kYD.js";const g=JSON.parse('{"title":"Agent 核心研究与竞品动态 · 2026-09-15","description":"2026-09-15 Agent 核心研究者、Runtime 项目与 CodeFlowMu 竞品双源监测日档。","frontmatter":{"title":"Agent 核心研究与竞品动态 · 2026-09-15","description":"2026-09-15 Agent 核心研究者、Runtime 项目与 CodeFlowMu 竞品双源监测日档。","outline":[2,3]},"headers":[],"relativePath":"zh/runtime/daily-intelligence/2026-09-15.md","filePath":"zh/runtime/daily-intelligence/2026-09-15.md","lastUpdated":1789431029000}'),n={name:"zh/runtime/daily-intelligence/2026-09-15.md"};function i(c,e,s,p,d,l){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="agent-核心研究与竞品动态-·-2026-09-15" tabindex="-1">Agent 核心研究与竞品动态 · 2026-09-15 <a class="header-anchor" href="#agent-核心研究与竞品动态-·-2026-09-15" aria-label="Permalink to &quot;Agent 核心研究与竞品动态 · 2026-09-15&quot;">​</a></h1><blockquote><p>Asia/Shanghai · 仅收录达到 meaningful new developments 阈值的公开技术与产品变化。</p></blockquote><p><a href="./">返回每日动态索引</a></p><h2 id="当日结论" tabindex="-1">当日结论 <a class="header-anchor" href="#当日结论" aria-label="Permalink to &quot;当日结论&quot;">​</a></h2><p>今天最强的共振是：<strong>执行权正在从“Agent/Session 还活着”继续收缩到“用户是否授权了这次扩张、当前 Run 到底是谁、当前凭证属于谁、当前 Sandbox 包身份是什么、失败后到底有没有正证据允许重试”。</strong></p><p>这意味着生产级 Agent 需要把 <strong>Intent、Run Identity、Principal、Host/Package Identity、Effect Outcome</strong> 分开建模；任何一个旧对象都不能替代其余几个对象。</p><h2 id="_1-yue-zhao-anywhere-agents-未经用户请求的-fan-out-被明确列为治理违规-prun-同时改成-agy-only" tabindex="-1">1. Yue Zhao / anywhere-agents：未经用户请求的 fan-out 被明确列为治理违规，prun 同时改成 Agy-only <a class="header-anchor" href="#_1-yue-zhao-anywhere-agents-未经用户请求的-fan-out-被明确列为治理违规-prun-同时改成-agy-only" aria-label="Permalink to &quot;1. Yue Zhao / anywhere-agents：未经用户请求的 fan-out 被明确列为治理违规，prun 同时改成 Agy-only&quot;">​</a></h2><p><strong>状态：COMMITTED</strong></p><p>赵岳在 <code>anywhere-agents</code> 连续提交两项直接相关的治理修订：</p><ul><li><a href="https://github.com/yzhao062/anywhere-agents/commit/e26fafb43962abe6fb3cd0aa12940988b66d8131" target="_blank" rel="noreferrer">e26fafb</a>：<code>prun</code> 不再使用 Sonnet/Claude subagent，也不再把 Workflow 当 fallback；所有 unit 只由 Agy 执行。背景是 2026-09-13 的真实使用中，Sonnet units 及其 descendants 成为 Claude 五小时窗口消耗的最大可识别来源之一，且一个 unit 曾自行再生成 10 个 nested agents。</li><li><a href="https://github.com/yzhao062/anywhere-agents/commit/28acaafe81e620c05f11df3a1b46e551da85b244" target="_blank" rel="noreferrer">28acaaf</a>：记录另一项真实事故——用户只要求“看一下仓库”，session 却主动发起 4 个 Sonnet prun unit、其中一个又生成 10 个 nested agents，同时还启动了 14-agent Opus Workflow。新规则要求：并行 fan-out 必须先向用户提出，由用户选择 prun 或 Workflow；只有用户已经明确选择当前路线时，才可在约定范围内继续。</li></ul><p>值得注意的是，这条“不得擅自 fan-out”目前<strong>刻意保持为语义规则，而不是机械 Hook</strong>：是否已经得到用户授权依赖对话上下文，错误的确定性 Hook 反而可能阻断用户已经授权的并行工作。</p><p><strong>为什么重要：</strong> Subagent 数量不只是性能参数，它同时改变成本、权限面、外部副作用数量和审计复杂度。Agent 自行决定“多开几十个 Worker”本质上是在扩大执行授权。</p><p><strong>与 CodeFlowMu/FCoP 的关系：</strong> 这与 CodeFlowMu 的角色边界高度一致：PM 可以组织工作，但正式团队扩张、并行 fan-out、跨 Host 执行应有明确的授权来源；内部辅助 Agent 不能因为模型觉得“并行更快”就自动成为正式协作者。</p><p><strong>值得互动：非常高。</strong> 技术切入：<em>是否会把“用户已授权 fan-out”的 evidence 与每个 worker 的 parent/run identity 一起写入 dispatch ledger，从而让后续审计区分用户授权并行与 Agent 自主扩权？</em></p><h2 id="_2-openai-agents-python-realtime-approval-存在真实-fail-open-路径-候选修复改为-strict-fail-closed" tabindex="-1">2. OpenAI Agents Python：Realtime approval 存在真实 fail-open 路径，候选修复改为 strict fail-closed <a class="header-anchor" href="#_2-openai-agents-python-realtime-approval-存在真实-fail-open-路径-候选修复改为-strict-fail-closed" aria-label="Permalink to &quot;2. OpenAI Agents Python：Realtime approval 存在真实 fail-open 路径，候选修复改为 strict fail-closed&quot;">​</a></h2><p><strong>状态：OPEN · PR #5029</strong></p><p>PR <a href="https://github.com/openai/openai-agents-python/pull/5029" target="_blank" rel="noreferrer">#5029</a> 发现 Realtime session 在调用共享 <code>needs_approval</code> evaluator 时传入了 <code>strict=False</code>。因此一个无效设置，例如 <code>needs_approval=&quot;always&quot;</code>，会被解释成 <code>False</code>，工具可以<strong>绕过原本预期的审批直接执行</strong>；而 core runner 对同一输入已经会抛出 <code>UserError</code>。</p><p>候选修复让 Realtime 与 core runner 使用相同 strict 行为：无效 approval 配置在任何工具调用之前报错，不再静默降级为“不需要审批”。该 PR 尚未合入。</p><p><strong>为什么重要：</strong> Approval policy 的 schema/configuration error 不能被当成“允许”。这是最典型的治理 fail-open。</p><p><strong>与 CodeFlowMu/FCoP 的关系：</strong> <code>approval_required</code>、授权边界、Host 准入和 EVAL 门禁都应遵循同一原则：<strong>Invalid / Unknown / Unparseable policy = No Authority</strong>，而不是默认继续执行。</p><p><strong>值得互动：高。</strong> 技术切入：<em>是否考虑把 approval-policy parsing outcome 也写入 tool-call receipt，使审计能证明该调用使用的是哪一个已验证 policy revision？</em></p><h2 id="_3-openai-codex-windows-sandbox-开始绑定正式-package-identity-而不是依赖复制-helper-或-path" tabindex="-1">3. OpenAI Codex：Windows Sandbox 开始绑定正式 Package Identity，而不是依赖复制 helper 或 PATH <a class="header-anchor" href="#_3-openai-codex-windows-sandbox-开始绑定正式-package-identity-而不是依赖复制-helper-或-path" aria-label="Permalink to &quot;3. OpenAI Codex：Windows Sandbox 开始绑定正式 Package Identity，而不是依赖复制 helper 或 PATH&quot;">​</a></h2><p><strong>状态：MERGED · #45542 / #45550</strong></p><p>两项 9 月 15 日前后合入的 Windows Sandbox 改造形成一条完整链：</p><ul><li>PR <a href="https://github.com/openai/codex/pull/45542" target="_blank" rel="noreferrer">#45542</a> 增加 service-managed <code>registered_core</code> provisioning：为 managed sandbox accounts 注册 app package，记录 runner aliases，并根据 service package family + installed version 认证调用者。只有 package registration 和 AppData metadata grants 都成功后才发布 runtime readiness；另一个 owner 或 legacy setup 不能覆盖已注册 sandbox account。</li><li>PR <a href="https://github.com/openai/codex/pull/45550" target="_blank" rel="noreferrer">#45550</a> 让 Sandbox 真正通过 service-recorded execution aliases 启动 registered runner，并在发命令前验证 ownership、OS package identity 和 staged runner image；明确不 fallback 到 copied helper 或 PATH lookup。package context 还会传给 sandbox descendants，支持从受保护 package directory 启动执行文件。</li></ul><p><strong>为什么重要：</strong> 这把“Sandbox 里运行的是哪个二进制”从路径约定升级成可验证的软件包身份。对 Windows 产品尤其重要，因为安装、更新、service、sandbox account 和执行文件如果各自只靠路径猜测，很容易在升级或恢复后漂移。</p><p><strong>与 CodeFlowMu/FCoP 的关系：</strong> CodeFlowMu 的 Host 准入可以继续向 <code>Host Product Identity → Installed Package Identity → Service Owner → Sandbox Runtime Identity → Executable Alias</code> 收敛，而不是只证明“官方版本号 PASS”。</p><p><strong>值得互动：非常高。</strong> 技术切入：<em>registered package identity 是否会进一步进入每个 sandbox execution receipt，使恢复后的 Run 能证明自己使用的是哪一代安装包与 service ownership？</em></p><h2 id="_4-superset-cloud-workspace-已能以-当前真人-的-github-身份-commit、push、开-pr" tabindex="-1">4. Superset：Cloud Workspace 已能以“当前真人”的 GitHub 身份 commit、push、开 PR <a class="header-anchor" href="#_4-superset-cloud-workspace-已能以-当前真人-的-github-身份-commit、push、开-pr" aria-label="Permalink to &quot;4. Superset：Cloud Workspace 已能以“当前真人”的 GitHub 身份 commit、push、开 PR&quot;">​</a></h2><p><strong>状态：MERGED 到 <code>sandbox-v2</code> 分支；尚不能等同于 production rollout</strong></p><p>PR <a href="https://github.com/superset-sh/superset/pull/7555" target="_blank" rel="noreferrer">#7555</a> 增加个人 GitHub connection。每个用户可以保存加密的 user-to-server token；刷新在 per-user advisory lock 下完成，因为 refresh token 会旋转，并发刷新可能互相失效。</p><p>在 Cloud Workspace 中，如果 creator 已连接个人 GitHub：</p><ul><li>GitHub firewall policy 使用该真人的 token，而不是组织 App token；</li><li>commit 的 author/committer 使用该真人的 GitHub no-reply identity；</li><li><code>gh</code>/PR 也以该真人身份执行；</li><li>创建 workspace 前就检查该真人是否能访问环境中的 repository；</li><li>长期无人值守 workspace 每 30 分钟由 host-service 用 workspace host secret 请求重新应用 credential policy，<strong>workspace 本身不持有 token</strong>。</li></ul><p>项目已用真实 Vercel box 验证 commit/push/PR attribution；但 30 分钟刷新定时器、8 小时 token refresh 和 disconnect revocation 尚未做 live verification，而且该 PR 合入的是 <code>sandbox-v2</code> 分支，不应提前写成已正式上线。</p><p><strong>为什么重要：</strong> Digital Employee Identity 与 Human Principal 被进一步拆开。同一个 Cloud Agent 可以持续存在，但每一次 GitHub effect 必须知道“代表哪个真人做”。</p><p><strong>与 CodeFlowMu/FCoP 的关系：</strong> 与此前 Paperclip 的 operation-time principal 高度共振。CodeFlowMu 后续若允许多个 ADMIN/成员共同使用同一个数字员工，应明确 <code>Employee → Current Instruction Principal → Credential Scope → Effect Attribution</code>。</p><p><strong>学习：非常高｜竞争风险：非常高｜雷达判断：Superset 已进入主雷达，应增加“真人操作归属 / unattended credential refresh”维度。</strong></p><p><strong>值得互动：非常高。</strong> 技术切入：<em>个人 GitHub principal 是否会绑定到具体 Run/instruction generation，而不是只绑定 workspace creator，从而支持同一长期 workspace 被不同真人先后驱动？</em></p><h2 id="_5-paperclip-pause-被-recovery-错读成-预算耗尽-一次-sweep-可把几十个正常任务永久打成-blocked" tabindex="-1">5. Paperclip：Pause 被 Recovery 错读成“预算耗尽”，一次 sweep 可把几十个正常任务永久打成 Blocked <a class="header-anchor" href="#_5-paperclip-pause-被-recovery-错读成-预算耗尽-一次-sweep-可把几十个正常任务永久打成-blocked" aria-label="Permalink to &quot;5. Paperclip：Pause 被 Recovery 错读成“预算耗尽”，一次 sweep 可把几十个正常任务永久打成 Blocked&quot;">​</a></h2><p><strong>状态：OPEN · PR #13443</strong></p><p>PR <a href="https://github.com/paperclipai/paperclip/pull/13443" target="_blank" rel="noreferrer">#13443</a> 报告了一个很有代表性的恢复事故：operator 主动把 Company 设为 <code>paused</code> 后，<code>budgets.getInvocationBlock</code> 也返回 invocation block；stranded recovery sweep 却把所有 block 都解释成“over budget”，于是把正常 assigned issue 改为 <code>blocked</code> 并添加 recovery action。</p><p>真实观测中，一个 paused company 在一次 sweep 里有 <strong>28 个 issue</strong> 被错误改为 blocked，整个 pause window 共 <strong>36 个</strong>；其中 4 个 watchdog issue 创建仅 6 秒就被错误处理。更严重的是，resume company 后这些 <code>blocked</code> issue 不会自动恢复，因为它们没有 dispatch queue、monitor 或真实 blocker，只能人工修复。</p><p>候选修复让 invocation block 显式携带 <code>cause=company_paused | budget_exhausted</code>，Recovery 对 paused company 只 skip，不进行 escalation，并补上 mid-sweep pause race 测试。PR 尚未合入。</p><p><strong>为什么重要：</strong> “停止工作”与“工作失败”是两种完全不同的业务事实。Recovery 如果把暂停、预算、权限、网络和 crash 都压成一个 Blocked，就会自己制造不可恢复状态。</p><p><strong>与 CodeFlowMu/FCoP 的关系：</strong> 这正好支持把 <code>Pause/Stop</code> 作为独立授权状态，而不是生命周期失败。轨道机/Recovery 不应对 ADMIN 的暂停决定做语义重写。</p><p><strong>学习：非常高｜竞争风险：很高｜雷达判断：Paperclip 继续一线；Recovery 原因码与可逆控制值得重点跟踪。</strong></p><p><strong>值得互动：高。</strong> 技术切入：<em>是否会把 invocation-block cause 升级成稳定的 typed control fact，并禁止 Recovery 将 operator pause 物化成业务终态？</em></p><h2 id="_6-orca-restart-recovery-终于停止用-没找到-推断-没送达-并同时开始重建-canonical-run-identity" tabindex="-1">6. Orca：Restart Recovery 终于停止用“没找到”推断“没送达”，并同时开始重建 canonical Run Identity <a class="header-anchor" href="#_6-orca-restart-recovery-终于停止用-没找到-推断-没送达-并同时开始重建-canonical-run-identity" aria-label="Permalink to &quot;6. Orca：Restart Recovery 终于停止用“没找到”推断“没送达”，并同时开始重建 canonical Run Identity&quot;">​</a></h2><p><strong>状态：OPEN · #20723；OPEN stacked series · #20717/#20718</strong></p><p>PR <a href="https://github.com/stablyai/orca/pull/20723" target="_blank" rel="noreferrer">#20723</a> 修复一个真实 duplicate-dispatch 风险。连接在 provider acknowledgement 前崩溃后，Orca 会从 transcript history 推断消息是否送达；但旧代码使用的 history window <strong>按构造就是空的</strong>，因此会把 comparable unsettled submission 判成 <code>rejected/not_delivered</code>。<code>rejected</code> 又允许旋转 client message id，Retry 最终可能把 provider 已经执行过的 prompt 再发一次。</p><p>候选修复删除这种二手 <code>not_delivered</code> 推断：只有 positive match 才进入 <code>accepted</code>；没有正证据就继续保持 <code>unknown</code>；<code>rejected</code> 只允许来自 provider 直接拒绝或可以证明 frame 从未到达 child 的一手事实。已经由旧版本写成 <code>recovered rejection</code> 的记录也不再自动获得 rotate/retry 权。</p><p>与此同时，#20717 / #20718 在做更深的身份重构：canonical status row 改由 <strong>Orca-minted <code>runId</code></strong> 作为主键，而 provider session id 只是 alias set。原因来自真实测量：两个并发 <code>claude --resume &lt;same-id&gt;</code> 可以拥有同一个 provider session id，却同时成为两个活 Run、甚至写向不同 branch。因此 provider session id 不能作为唯一 Agent Identity。child work 也获得 host-minted <code>childWorkId</code>，并保留 <code>unverifiable</code> 状态；当前只把拥有可信完整 scope 的 structured/native-chat session 迁入 canonical ownership，PTY/relay 缺少 execution host/WSL/workspace 等事实时宁愿留在 legacy adapter，也不伪造 scope。</p><p><strong>为什么重要：</strong> 这里同时回答了两个生产问题：<code>absence ≠ negative evidence</code>，以及 <code>Provider Session ID ≠ Run Identity</code>。</p><p><strong>与 CodeFlowMu/FCoP 的关系：</strong> CodeFlowMu 可以进一步明确：<code>Agent/Role Identity</code>、<code>Run Identity</code>、<code>Provider Session Alias</code>、<code>Child Work Identity</code>、<code>Delivery Settlement</code> 是不同字段；恢复时不能用任意一个代替其他对象。</p><p><strong>学习：非常高｜竞争风险：中高｜雷达判断：继续上调 Orca 的 identity / recovery / multi-host 权重。</strong></p><p><strong>值得互动：非常高。</strong> 技术切入：<em>canonical runId 是否最终会成为 delivery receipt、child work、workspace/host scope 与 replay eligibility 的共同外键？</em></p><h2 id="_7-crewai-运行异常会让同一个-tool-在一次-attempt-内被调用两次-形成真实-duplicate-side-effect-窗口" tabindex="-1">7. CrewAI：运行异常会让同一个 Tool 在一次 attempt 内被调用两次，形成真实 duplicate side-effect 窗口 <a class="header-anchor" href="#_7-crewai-运行异常会让同一个-tool-在一次-attempt-内被调用两次-形成真实-duplicate-side-effect-窗口" aria-label="Permalink to &quot;7. CrewAI：运行异常会让同一个 Tool 在一次 attempt 内被调用两次，形成真实 duplicate side-effect 窗口&quot;">​</a></h2><p><strong>状态：OPEN · Issue #7449 的候选修复之一 PR #7458</strong></p><p>PR <a href="https://github.com/crewAIInc/crewAI/pull/7458" target="_blank" rel="noreferrer">#7458</a> 发现 <code>ToolUsage._use/_ause</code> 中，本来只应该保护参数 schema filtering 的 <code>try/except</code> 把 <code>tool.invoke()/ainvoke()</code> 也包了进去。如果 Tool 自身运行时抛异常，这个异常会被误当成“参数过滤失败”，随后系统会在<strong>同一个 outer attempt 内用未过滤参数再次调用同一个 Tool</strong>。</p><p>因此一个失败 Tool 不是“一次 attempt 一次调用”，而可能变成两次；另一个同类 PR 还指出，在默认 <code>_max_parsing_attempts=3</code> 情况下，持续失败的 Tool 最多可实际执行 6 次。对有支付、写库、发消息等非幂等副作用的工具，这是典型 duplicate-effect 风险。</p><p>候选修复只把 schema extraction/filtering 留在 <code>try/except</code>，实际 invoke 每个 outer attempt 精确执行一次。当前有多个围绕同一 Issue 的候选 PR，尚不能写成主线已修复。</p><p><strong>为什么重要：</strong> Retry policy 之外还可能隐藏“隐式第二次调用”。只看高层 <code>attempt_count</code> 无法审计真实副作用次数。</p><p><strong>与 CodeFlowMu/FCoP 的关系：</strong> Tool execution receipt 应记录真实 invocation identity，而不是只记录 Agent attempt；如果 Tool effect 不具备 idempotency key，一次 attempt 内任何隐式重入都应该被认为是严重治理缺陷。</p><p><strong>值得互动：高。</strong> 技术切入：<em>CrewAI 是否会为每个真实 tool invocation 分配稳定 invocation/effect ID，使 outer retry 与实际 effect 次数可以独立审计？</em></p><h2 id="跨项目共振" tabindex="-1">跨项目共振 <a class="header-anchor" href="#跨项目共振" aria-label="Permalink to &quot;跨项目共振&quot;">​</a></h2><p>今天可以收敛成一个更精确的 Runtime 模型：</p><blockquote><p><strong>“还在同一个工作里”不再是授权证明。用户授权、Run、Provider Session、真人 Principal、Sandbox Package、Pause 原因和 Tool Effect 都必须有各自身份。</strong></p></blockquote><p>对 CodeFlowMu/FCoP，可继续固定为：</p><p><strong>User Intent / Fan-out Authorization → Role &amp; Run Identity → Human Principal / Credential Scope → Host &amp; Package Identity → Call-time Admission → Effect Invocation Identity → Evidence-driven Settlement / Replay Eligibility</strong>。</p><p>尤其有三个值得进入长期工程规则的结论：</p><ol><li><strong>没有正证据时保留 Unknown，不能把 Absence 推成失败。</strong></li><li><strong>Pause/Stop 是可逆控制决定，不是业务失败。</strong></li><li><strong>一次 Agent attempt 与一次真实 Tool effect 不是同一计数单位。</strong></li></ol><h2 id="双源核查说明" tabindex="-1">双源核查说明 <a class="header-anchor" href="#双源核查说明" aria-label="Permalink to &quot;双源核查说明&quot;">​</a></h2><p>本轮同时检查 GitHub 一手变更、项目官方页面/Changelog、MCP 官方活动页和公开社交检索。Cursor 官方最新重大 Changelog 仍是 2026-09-10 的 Projects，没有 9 月 14–15 日的新正式发布；MCP 官方 9 月 14 日继续举行 Progressive Disclosure、Auth、Server Card 等工作组，但公开活动页没有比当前协议/代码一手材料更具体的新技术结论。公开 X 检索没有得到身份可可靠确认且技术增量高于上述一手 GitHub 内容的本人新讨论，因此未使用营销转发或疑似账号补数。</p>',73)])])}const h=o(n,[["render",i]]);export{g as __pageData,h as default};
